-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Marktmechanismen > Angebot
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Steigt das Angebot an IT-Dienstleistungen, wenn der Preis dafür steigt?', 2, '[{"text": "Ja", "correct": true, "because": "Höhere Preise erhöhen die Angebotsbereitschaft"}, {"text": "Nein", "correct": false, "because": "Angebot steigt mit dem Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Produktionskosten ein Faktor, der das Angebot an Softwarelizenzen beeinflusst?', 2, '[{"text": "Ja", "correct": true, "because": "Höhere Kosten verringern das Angebot"}, {"text": "Nein", "correct": false, "because": "Produktionskosten beeinflussen das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Angebot an IT-Hardware durch technologische Innovationen steigen?', 2, '[{"text": "Ja", "correct": true, "because": "Innovationen erhöhen die Produktionskapazität"}, {"text": "Nein", "correct": false, "because": "Technologie steigert das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird das Angebot an Programmierdienstleistungen durch staatliche Subventionen beeinflusst?', 2, '[{"text": "Ja", "correct": true, "because": "Subventionen senken Produktionskosten"}, {"text": "Nein", "correct": false, "because": "Subventionen wirken auf das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Bleibt das Angebot an IT-Produkten konstant, wenn der Marktpreis sinkt?', 2, '[{"text": "Nein", "correct": true, "because": "Sinkende Preise verringern das Angebot"}, {"text": "Ja", "correct": false, "because": "Angebot reagiert auf Preisänderungen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was beschreibt das Angebot eines IT-Betriebs am besten?', 2, '[{"text": "Die Menge an Produkten, die angeboten wird", "correct": true, "because": "Angebot ist die bereitgestellte Menge"}, {"text": "Die Nachfrage nach IT-Dienstleistungen", "correct": false, "because": "Das ist die Nachfrage"}, {"text": "Die Gewinnspanne des Betriebs", "correct": false, "because": "Nicht direkt das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erhöht das Angebot an Softwareentwicklungsdiensten?', 3, '[{"text": "Steigende Marktpreise", "correct": true, "because": "Höhere Preise fördern das Angebot"}, {"text": "Sinkende Produktionskosten", "correct": false, "because": "Auch korrekt, aber Preis ist primär"}, {"text": "Geringere Nachfrage", "correct": false, "because": "Verringert das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkung hat ein Rückgang der Produktionskosten auf das Angebot eines IT-Betriebs?', 3, '[{"text": "Das Angebot steigt", "correct": true, "because": "Niedrigere Kosten erhöhen die Angebotsmenge"}, {"text": "Das Angebot sinkt", "correct": false, "because": "Kostenrückgang fördert das Angebot"}, {"text": "Keine Auswirkung", "correct": false, "because": "Kosten beeinflussen das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Angebotskurve eines IT-Dienstleisters?', 2, '[{"text": "Eine Kurve, die das Angebot in Abhängigkeit vom Preis zeigt", "correct": true, "because": "Angebotskurve zeigt Preis-Mengen-Beziehung"}, {"text": "Eine Kurve der Nachfrage", "correct": false, "because": "Das ist die Nachfragekurve"}, {"text": "Eine fixe Linie", "correct": false, "because": "Angebot ist preisabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Technologie beim Angebot eines IT-Betriebs?', 3, '[{"text": "Sie kann das Angebot erhöhen", "correct": true, "because": "Technologie steigert die Effizienz"}, {"text": "Sie hat keinen Einfluss", "correct": false, "because": "Technologie beeinflusst das Angebot"}, {"text": "Sie verringert das Angebot", "correct": false, "because": "Technologie fördert das Angebot"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen das Angebot eines IT-Betriebs?', 4, '[{"text": "Marktpreis", "correct": true, "because": "Höhere Preise steigern das Angebot"}, {"text": "Produktionskosten", "correct": true, "because": "Kosten beeinflussen die Angebotsmenge"}, {"text": "Technologische Entwicklungen", "correct": true, "because": "Technologie erhöht die Kapazität"}, {"text": "Wetterbedingungen", "correct": false, "because": "Wenig Einfluss auf IT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen haben steigende Preise auf das Angebot eines IT-Betriebs?', 3, '[{"text": "Erhöhung der Angebotsmenge", "correct": true, "because": "Höhere Preise fördern das Angebot"}, {"text": "Mehr Produktionsanreize", "correct": true, "because": "Gewinnmotiv steigt"}, {"text": "Weniger Produktion", "correct": false, "because": "Preissteigerung fördert Produktion"}, {"text": "Gewinnsteigerung möglich", "correct": true, "because": "Höhere Preise erhöhen Gewinne"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können das Angebot an IT-Dienstleistungen verringern?', 4, '[{"text": "Sinkende Marktpreise", "correct": true, "because": "Niedrige Preise reduzieren das Angebot"}, {"text": "Steigende Produktionskosten", "correct": true, "because": "Höhere Kosten verringern das Angebot"}, {"text": "Technologische Rückschritte", "correct": true, "because": "Weniger Effizienz reduziert Angebot"}, {"text": "Höhere Nachfrage", "correct": false, "because": "Nachfrage beeinflusst Angebot nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind Teil der Angebotsfunktion eines IT-Betriebs?', 3, '[{"text": "Preis der Dienstleistung", "correct": true, "because": "Primärer Einflussfaktor"}, {"text": "Produktionskosten", "correct": true, "because": "Kosten beeinflussen das Angebot"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Beeinflusst Nachfrage, nicht Angebot"}, {"text": "Technologie", "correct": true, "because": "Technologie steigert das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet das Angebot von der Nachfrage für einen IT-Betrieb?', 3, '[{"text": "Angebot ist die bereitgestellte Menge", "correct": true, "because": "Definition von Angebot"}, {"text": "Nachfrage ist die gewünschte Menge", "correct": true, "because": "Definition von Nachfrage"}, {"text": "Angebot wird nur von Kunden bestimmt", "correct": false, "because": "Angebot hängt von Anbietern ab"}, {"text": "Nachfrage beeinflusst das Angebot nicht", "correct": false, "because": "Nachfrage kann Angebot beeinflussen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Höhere Preise steigern das Angebot eines IT-Betriebs. b) Sinkende Produktionskosten verringern das Angebot.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preise ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Technologische Innovationen erhöhen das Angebot an IT-Produkten. b) Angebot ist unabhängig vom Preis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Innovation ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Subventionen erhöhen das Angebot eines IT-Betriebs. b) Steigende Preise verringern das Angebot.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Subventionen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das Angebot an IT-Dienstleistungen steigt bei höheren Preisen. b) Produktionskosten haben keinen Einfluss auf das Angebot.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preise ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Angebot wird durch den Marktpreis beeinflusst. b) Angebot und Nachfrage sind dasselbe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preis ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

